mapper.select:
select * from idevelop_device_operation_detail t
where
	t.device_code = #{deviceNo,jdbcType=VARCHAR}
  and t.operation_no = #{applicationId,jdbcType=VARCHAR}

SELECT ua.*, unit.dept_name AS companyName, dept.dept_name AS deptName, ss.subnet_name AS subnetName FROM idevelop_safeaccess_user_access ua LEFT JOIN idevelop_dept unit ON unit.id = ua.company and unit.is_deleted = 0 LEFT JOIN idevelop_dept dept ON dept.id = ua.dept_code and dept.is_deleted = 0 LEFT JOIN idevelop_safeaccess_subnet ss ON ss.id = ua.subnet_id and ss.is_deleted = 0 WHERE ua.is_deleted = 0 and ua.company = #{param.company} and ua.mac_address = #{param.macAddress} and ua.ip_address like concat('%',#{param.ipAddress},'%') and ua.device_code like CONCAT('%',#{param.deviceCode},'%')
and ua.device_type = #{param.deviceType} and ua.approveu_user = #{param.approveuUser}
and ua.mi_charge_user = #{param.miChargeUser}
and ua.mi_user = #{param.miUser} and ua.is_access = #{param.isAccess} and ua.subnet_id = #{param.subnetId} and ua.region_code like CONCAT(#{param.regionCode},'%')
ORDER BY ua.create_time DESC
